619	    /**
620	     Tests if the attribute is {@code srcset} (case-insensitive), which holds a comma-separated list of image
621	     candidate URLs and so gets per-candidate cleaning in the {@link Cleaner}.
622	     */
623	    static boolean isSrcset(String attrKey) {
624	        return attrKey.equalsIgnoreCase(Srcset);
625	    }
