627	    /**
628	     Tests if the attribute is the inline CSS {@code style} attribute (case-insensitive), whose declarations are
629	     * parsed and checked individually in the {@link Cleaner}, rather than treated as a single URL value.
630	     */
631	    static boolean isStyle(String attrKey) {
632	        return attrKey.equalsIgnoreCase(Style);
633	    }
