635	    /**
636	     Cleans an inline {@code style} attribute value declaration by declaration. Declarations that are malformed, or
637	     * that reference an external resource ({@code url(...)}, {@code @import}, or the legacy {@code expression(...)}
638	     * function) whose URL fails the protocol rules configured for the tag's style attribute, are removed individually;
639	     * the surviving declarations keep their original order and text. Does not throw on malformed CSS.
640	
641	     @param tagName the tag the attribute is on; selects the applicable protocol configuration
642	     @param el the element the attribute is on, to resolve URLs against its base URI
643	     @param value the source style attribute value
644	     @return the cleaned value, or {@code null} if no declaration survives (in which case the attribute is removed)
645	     */
646	    String cleanStyle(String tagName, Element el, String value) {
647	        return StyleCleaner.clean(this, tagName, el, value);
648	    }
649	
650	    /**
651	     Finds the protocol configuration applicable to external references inside an allowed {@code style} attribute on
652	     * the given tag, following the same tag to {@code :all} fallback as the other attribute checks. Unlike a
653	     * {@code href} or {@code srcset}, removing every configured protocol does not open style up to arbitrary
654	     * schemes: when the caller has configured nothing for style (or removed it all), references are restricted to
655	     * the safe default set ({@code http}, {@code https}, and same-document fragments).
656	     */
657	    private Set<Protocol> styleProtocols(TagName tag) {
658	        Set<AttributeKey> okSet = attributes.get(tag);
659	        if (okSet != null && okSet.contains(StyleKey)) {
660	            Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
661	            if (attrProts != null && attrProts.containsKey(StyleKey)) return attrProts.get(StyleKey);
662	            return DefaultStyleProtocols;
663	        }
664	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
665	        if (enforcedSet != null && enforcedSet.containsKey(StyleKey)) return DefaultStyleProtocols;
666	        return !tag.equals(AllTag) ? styleProtocols(AllTag) : DefaultStyleProtocols;
667	    }
668	
669	    /**
670	     Validates one external reference found inside a style declaration against the tag's configured style protocols,
671	     * applying the same obfuscation-resistant rules as a {@code srcset} candidate. {@code javascript:} and
672	     * {@code vbscript:} are always rejected (even after control-character stripping and percent-decoding), and so is
673	     * any unknown scheme; a {@code data:} reference passes only when {@code data} is an explicitly allowed protocol
674	     * and its media type is inert. Relative references are resolved against the element's document base URI, and an
675	     * unresolvable reference (such as a relative URL with no base URI) is rejected.
676	     */
677	    boolean isSafeStyleUrl(String tagName, Element el, String url) {
678	        Set<Protocol> protocols = styleProtocols(TagName.valueOf(tagName));
679	        if (!isSoundUrlValue(url)) return false;
680	
681	        // script-bearing schemes are always rejected, after undoing every encoding layer a browser applies
682	        // (HTML entities are already decoded by the parser; CSS escapes by StyleCleaner): strip control bytes and
683	        // leniently percent-decode before testing the prefix
684	        String decoded = lowerCase(stripControlChars(percentDecode(url)));
685	        if (decoded.startsWith("javascript:") || decoded.startsWith("vbscript:")) return false;
686	
687	        // a protocol-relative reference ("//host", or the backslash spellings a browser's special-scheme parser
688	        // treats identically) would inherit the base document's scheme during resolution; it carries no allowed
689	        // scheme of its own and so is rejected outright, regardless of the configured protocol set. The check runs
690	        // only after CSS escapes (StyleCleaner), percent-decoding, and control-char stripping have been undone, so
691	        // e.g. "\/\/host", "%2f%2fhost", and "%5c%5chost" are recognized just like "//host".
692	        if (startsWithAuthority(decoded)) return false;
693	
694	        if (!isSafeDecodedScheme(url, protocols)) return false;
695	        if (decoded.startsWith("data:") && !isSafeDataUrl(url, protocols)) return false;
696	
697	        // resolve relative references against the document base, applying the same rules as a srcset candidate:
698	        // an unresolvable reference (e.g. no base URI) fails, and the surviving declaration keeps its source spelling
699	        String resolved = StringUtil.resolve(el.baseUri(), url);
700	        if (resolved.isEmpty() && !StringUtil.hasHttpScheme(url)) resolved = url;
701	        return isSafeProtocol(resolved, protocols);
702	    }
703	
704	    /**
705	     Tests whether an (already CSS-unescaped, percent-decoded, control-stripped, lower-cased) reference begins with an
706	     authority component with no scheme of its own, mirroring how a browser's special-scheme URL parser reads the
707	     prefix: {@code //host}, or a leading backslash followed by either slash or backslash ({@code \\host},
708	     {@code \/host}). Such a network-path reference inherits the base document's scheme and is never an allowed,
709	     independently-schemed absolute URL. A single leading slash stays a root-relative, same-origin reference —
710	     including {@code /\path}, whose second character is a backslash but which the browser does not read as the
711	     start of an authority — and so is left to normal base-URI resolution.
712	     */
713	    private static boolean startsWithAuthority(String decoded) {
714	        if (decoded.length() < 2) return false;
715	        char first = decoded.charAt(0);
716	        char second = decoded.charAt(1);
717	        if (first == '/') return second == '/'; // "/\" is a root-relative path, not an authority
718	        return first == '\\' && (second == '/' || second == '\\'); // browsers tolerate backslashes under special schemes
719	    }
720	
721	    /**
722	     Allows a {@code data:} URL only when {@code data} is an explicitly configured protocol and the embedded media
723	     * type is a known inert type (an image, or plain text); {@code data:text/html}, {@code data:image/svg+xml}, and
724	     * any executable or unknown media type are rejected.
725	     */
726	    private static boolean isSafeDataUrl(String url, Set<Protocol> protocols) {
727	        boolean dataAllowed = false;
728	        for (Protocol protocol : protocols) {
729	            if (protocol.toString().equals("data")) { dataAllowed = true; break; }
730	        }
731	        if (!dataAllowed) return false;
732	        String rest = url.substring("data:".length());
733	        int semi = rest.indexOf(';');
734	        int comma = rest.indexOf(',');
735	        int end = semi >= 0 ? semi : comma;
736	        if (end < 0) end = rest.length();
737	        String mediaType = rest.substring(0, end).trim().toLowerCase(Locale.ROOT);
738	        if (mediaType.isEmpty()) mediaType = "text/plain"; // the default for data: URLs
739	        if (mediaType.startsWith("image/"))
740	            return !mediaType.equals("image/svg+xml"); // SVG can carry script
741	        return mediaType.equals("text/plain");
742	    }
743	
744	    /**
745	     Cleans a {@code srcset} attribute value, candidate by candidate. Candidates with invalid syntax (missing URL,
746	     empty candidates, malformed descriptors, or trailing junk) are dropped, as are those whose URL fails the
747	     protocol checks configured for the attribute on this tag. Surviving candidates keep their original order and
748	     are normalized to {@code url descriptor, url descriptor} form. Does not throw on malformed input.
749	
750	     @param tagName the tag the attribute is on; selects the applicable protocol configuration
751	     @param el the element the attribute is on, to resolve URLs against its base URI
752	     @param value the source srcset attribute value
753	     @return the cleaned value, or {@code null} if no candidates survive (in which case the attribute is removed)
754	     */
755	    String cleanSrcset(String tagName, Element el, String value) {
756	        Set<Protocol> protocols = srcsetProtocols(TagName.valueOf(tagName));
757	        StringBuilder sb = StringUtil.borrowBuilder();
758	
759	        int pos = 0, length = value.length();
760	        while (pos <= length) {
761	            // find the end of this candidate: a comma separates candidates, unless it is within the URL and directly
762	            // followed by a non-whitespace, non-comma character (e.g. the comma in a data: URL). Consecutive
763	            // separators produce empty candidates, which are invalid.
764	            int start = pos, end = pos;
765	            boolean inUrl = true; // still scanning the URL run (no whitespace after URL content yet)
766	            boolean started = false; // seen non-whitespace content in this candidate
767	            while (end < length) {
768	                char c = value.charAt(end);
769	                if (c == ',') {
770	                    if (inUrl && started && end + 1 < length && !isSrcsetSpace(value.charAt(end + 1)) && value.charAt(end + 1) != ',')
771	                        end++; // comma is part of the URL
772	                    else
773	                        break; // candidate separator
774	                } else {
775	                    if (isSrcsetSpace(c)) {
776	                        if (started) inUrl = false;
777	                    } else {
778	                        started = true;
779	                    }
780	                    end++;
781	                }
782	            }
783	            appendSrcsetCandidate(el, value, start, end, protocols, sb);
784	            if (end >= length) break;
785	            pos = end + 1; // step past the separator comma
786	        }
787	
788	        if (sb.length() == 0) {
789	            StringUtil.releaseBuilderVoid(sb);
790	            return null;
791	        }
792	        return StringUtil.releaseBuilder(sb);
793	    }
794	
795	    /**
796	     Validates and appends a single srcset candidate (the {@code value} range {@code start}..{@code end}) to
797	     {@code sb}. Invalid or unsafe candidates are silently dropped; their text is never recombined into new URLs.
798	     */
799	    private void appendSrcsetCandidate(Element el, String value, int start, int end, Set<Protocol> protocols, StringBuilder sb) {
800	        // trim ASCII whitespace from the candidate
801	        while (start < end && isSrcsetSpace(value.charAt(start))) start++;
802	        while (end > start && isSrcsetSpace(value.charAt(end - 1))) end--;
803	        if (start == end) return; // empty candidate (e.g. from consecutive separators)
804	
805	        // the URL is the leading run of non-whitespace
806	        int urlEnd = start;
807	        while (urlEnd < end && !isSrcsetSpace(value.charAt(urlEnd))) urlEnd++;
808	        String url = value.substring(start, urlEnd);
809	        if (isOrphanDescriptor(url)) return; // a descriptor cannot stand in for the required URL
810	
811	        // an optional descriptor may follow, introduced by at least one ASCII space
812	        String descriptor = null;
813	        if (urlEnd < end) {
814	            if (value.charAt(urlEnd) != ' ') return; // the descriptor must be space-separated from the URL
815	            int descStart = urlEnd;
816	            while (descStart < end && value.charAt(descStart) == ' ') descStart++;
817	            int descEnd = descStart;
818	            while (descEnd < end && !isSrcsetSpace(value.charAt(descEnd))) descEnd++;
819	            if (descEnd != end) return; // unexpected content after the descriptor (e.g. a second descriptor)
820	            descriptor = value.substring(descStart, descEnd);
821	            if (!isValidSrcsetDescriptor(descriptor)) return;
822	        }
823	
824	        if (protocols != null && !isSafeSrcsetUrl(el, url, protocols)) return;
825	
826	        if (sb.length() > 0) sb.append(", ");
827	        sb.append(url);
828	        if (descriptor != null) sb.append(' ').append(descriptor);
829	    }
830	
831	    /**
832	     Finds the protocol configuration applicable to {@code srcset} on the given tag, following the same tag to
833	     {@code :all} fallback as {@link #isSafeAttribute}, so that per-tag differences neither widen nor narrow each
834	     other. Returns {@code null} when URLs are unrestricted.
835	     */
836	    private Set<Protocol> srcsetProtocols(TagName tag) {
837	        Set<AttributeKey> okSet = attributes.get(tag);
838	        if (okSet != null && okSet.contains(SrcsetKey)) {
839	            Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
840	            return attrProts != null ? attrProts.get(SrcsetKey) : null;
841	        }
842	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
843	        if (enforcedSet != null && enforcedSet.containsKey(SrcsetKey)) return null;
844	        return !tag.equals(AllTag) ? srcsetProtocols(AllTag) : null;
845	    }
846	
847	    private boolean isSafeSrcsetUrl(Element el, String url, Set<Protocol> protocols) {
848	        // apply the same structural rules as for a single-value URL attribute: no control characters or inner
849	        // whitespace, and no bare scheme (e.g. "javascript:") with nothing after the colon
850	        if (!isSoundUrlValue(url)) return false;
851	        // the scheme must still be allowed after percent-decoding and stripping control characters, so that a
852	        // dangerous scheme cannot hide behind e.g. "java%73cript:", "%6Aavascript:", "%00javascript:", or leading
853	        // whitespace and control bytes
854	        if (!isSafeDecodedScheme(url, protocols)) return false;
855	
856	        String value = StringUtil.resolve(el.baseUri(), url);
857	        if (value.isEmpty() && !StringUtil.hasHttpScheme(url))
858	            value = url; // if it could not be made absolute, run as-is to allow custom unknown protocols
859	        return isSafeProtocol(value, protocols);
860	    }
861	
862	    /**
863	     Checks the scheme of a candidate URL against the configured protocols, after undoing obfuscations that could hide
864	     a dangerous scheme from a naive prefix check. A real URL scheme is terminated by a <b>literal</b> colon, so the
865	     raw value is scanned for its first colon; percent-encoded bytes and ASCII control characters in the scheme run
866	     before that colon are normalized (e.g. {@code java%73cript:}, {@code %6Aavascript:}, and {@code java%00script:}
867	     all reveal {@code javascript:}). A value with no literal-colon scheme (a relative reference such as
868	     {@code x%3Ay.jpg} or an already-encoded {@code http%3a//host}) is left to the standard base-URI resolution
869	     rules, exactly like a single-value URL attribute. Never throws.
870	     */
871	    private static boolean isSafeDecodedScheme(String url, Set<Protocol> protocols) {
872	        int colon = url.indexOf(':');
873	        if (colon <= 0) return true; // no literal scheme separator: a relative / protocol-relative reference
874	
875	        String head = url.substring(0, colon);
876	        // the scheme run may only contain scheme characters or percent-escapes; anything else (e.g. a leading "//")
877	        // means this colon is not a scheme separator
878	        int length = head.length();
879	        boolean sawEscape = false;
880	        for (int i = 0; i < length; i++) {
881	            char c = head.charAt(i);
882	            if (c == '%') { sawEscape = true; continue; }
883	            boolean schemeChar = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
884	                || (c >= '0' && c <= '9') || c == '+' || c == '-' || c == '.';
885	            if (!schemeChar) return true; // not a scheme; defer to base-URI resolution
886	        }
887	        if (!sawEscape) return true; // an unescaped scheme is checked by the normal resolved-URL protocol test
888	
889	        // decode the escaped bytes and drop any revealed control characters, then confirm a well-formed scheme
890	        String decoded = stripControlChars(percentDecode(head));
891	        if (decoded.isEmpty() || !isSchemeAlpha(decoded.charAt(0))) return true;
892	        for (int i = 0; i < decoded.length(); i++) {
893	            char c = decoded.charAt(i);
894	            boolean schemeChar = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
895	                || (c >= '0' && c <= '9') || c == '+' || c == '-' || c == '.';
896	            if (!schemeChar) return true; // decoding revealed a non-scheme byte, so it is a relative reference
897	        }
898	
899	        String scheme = lowerCase(decoded);
900	        for (Protocol protocol : protocols) {
901	            String prot = protocol.toString();
902	            if (!prot.equals("#") && scheme.equals(prot)) return true; // the "#" pseudo-protocol never matches a scheme
903	        }
904	        return false;
905	    }
906	
907	    /** Removes ASCII control characters (0x00-0x1F and DEL), which browsers ignore when reading a URL scheme. */
908	    private static String stripControlChars(String value) {
909	        int length = value.length();
910	        StringBuilder stripped = null;
911	        for (int i = 0; i < length; i++) {
912	            char c = value.charAt(i);
913	            if (c <= 0x1f || c == 0x7f) {
914	                if (stripped == null) {
915	                    stripped = new StringBuilder(length);
916	                    stripped.append(value, 0, i);
917	                }
918	            } else if (stripped != null) {
919	                stripped.append(c);
920	            }
921	        }
922	        return stripped != null ? stripped.toString() : value;
923	    }
924	
925	    /**
926	     Leniently decodes {@code %XX} percent-escapes to their (ISO-8859-1 mapped) character. Malformed or incomplete
927	     escapes are left as-is. Used only to reveal an obfuscated URL scheme, so decoding never throws and charset
928	     subtleties outside the ASCII scheme are irrelevant.
929	     */
930	    private static String percentDecode(String url) {
931	        int length = url.length();
932	        if (length < 3 || url.indexOf('%') == -1) return url;
933	        StringBuilder decoded = null;
934	        for (int i = 0; i < length; i++) {
935	            char c = url.charAt(i);
936	            if (c == '%' && i + 2 < length) {
937	                int hi = Character.digit(url.charAt(i + 1), 16);
938	                int lo = Character.digit(url.charAt(i + 2), 16);
939	                if (hi >= 0 && lo >= 0) {
940	                    if (decoded == null) {
941	                        decoded = new StringBuilder(length);
942	                        decoded.append(url, 0, i);
943	                    }
944	                    decoded.append((char) ((hi << 4) | lo));
945	                    i += 2;
946	                    continue;
947	                }
948	            }
949	            if (decoded != null) decoded.append(c);
950	        }
951	        return decoded != null ? decoded.toString() : url;
952	    }
953	
954	    /**
955	     * Tests if a candidate's first (and only) whitespace-delimited token is a descriptor with no URL in front of it,
956	     * rather than a relative URL. Such an orphan has the <i>shape</i> of a width or density descriptor: a lowercase
957	     * {@code w} or {@code x} suffix, an optional single leading sign, and a non-empty remaining run of only digits and
958	     * dots, e.g. {@code 2x}, {@code 100w}, {@code 1.5x}, {@code 0w}, {@code -1x}, {@code +1x}, {@code 1.x},
959	     * {@code .5x}, or {@code 1.5.2x}. This is a purely syntactic shape test (it does not require the number to be
960	     * valid), because a token that can only be read as a descriptor attempt supplies no decidable URL. A genuine
961	     * relative reference always carries something a descriptor number can never hold — another letter
962	     * ({@code 1e3x}, {@code 1X}, {@code 2x.jpg}), a path separator ({@code ../2x}), or an internal or second sign
963	     * ({@code 1-2x}, {@code ++2x}) — and so is never mistaken for an orphan.
964	     */
965	    private static boolean isOrphanDescriptor(String token) {
966	        int length = token.length();
967	        if (length < 2) return false; // a bare "w"/"x" is a possible relative reference, not a descriptor attempt
968	        char suffix = token.charAt(length - 1);
969	        if (suffix != 'w' && suffix != 'x') return false;
970	        int i = 0;
971	        if (token.charAt(0) == '+' || token.charAt(0) == '-') i++; // at most one, leading sign
972	        if (i == length - 1) return false; // just a sign and suffix (e.g. "+w"): a relative reference, not a number
973	        for (; i < length - 1; i++) {
974	            char c = token.charAt(i);
975	            boolean numberChar = (c >= '0' && c <= '9') || c == '.';
976	            if (!numberChar) return false; // a letter, separator, or internal sign marks a real URL
977	        }
978	        return true;
979	    }
980	
981	    /**
982	     Validates a srcset descriptor: a positive integer followed by a lowercase {@code w} (e.g. {@code 100w}), or a
983	     positive number (digits, or digits.digits) followed by a lowercase {@code x} (e.g. {@code 2x}, {@code 1.5x}).
984	     Signs, exponents, a dot missing a side, and zero values are all invalid.
985	     */
986	    private static boolean isValidSrcsetDescriptor(String descriptor) {
987	        int length = descriptor.length();
988	        if (length < 2) return false;
989	        String number = descriptor.substring(0, length - 1);
990	        switch (descriptor.charAt(length - 1)) {
991	            case 'w': return isPositiveInteger(number);
992	            case 'x': return isPositiveNumber(number);
993	            default:  return false;
994	        }
995	    }
996	
997	    /** Tests if the value is all digits and greater than zero. */
998	    private static boolean isPositiveInteger(String number) {
999	        boolean nonZero = false;
1000	        for (int i = 0, length = number.length(); i < length; i++) {
1001	            char c = number.charAt(i);
1002	            if (c < '0' || c > '9') return false;
1003	            if (c != '0') nonZero = true;
1004	        }
1005	        return nonZero;
1006	    }
1007	
1008	    /** Tests if the value is digits, or digits.digits, and greater than zero. */
1009	    private static boolean isPositiveNumber(String number) {
1010	        int dot = number.indexOf('.');
1011	        if (dot == -1) return isPositiveInteger(number);
1012	        if (number.indexOf('.', dot + 1) != -1) return false; // at most one dot
1013	        String integer = number.substring(0, dot);
1014	        String fraction = number.substring(dot + 1);
1015	        if (!isDigits(integer) || !isDigits(fraction)) return false; // the dot needs digits on both sides
1016	        return isPositiveInteger(integer) || isPositiveInteger(fraction);
1017	    }
1018	
1019	    private static boolean isDigits(String value) {
1020	        for (int i = 0, length = value.length(); i < length; i++) {
1021	            char c = value.charAt(i);
1022	            if (c < '0' || c > '9') return false;
1023	        }
1024	        return value.length() > 0;
1025	    }
1026	
1027	    /** The ASCII whitespace characters: space, tab, newline, carriage return, and form feed. */
1028	    private static boolean isSrcsetSpace(char c) {
1029	        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
1030	    }
1031	
1032	    /** Tests if the character is an ASCII letter, the required first character of a URL scheme. */
1033	    private static boolean isSchemeAlpha(char c) {
1034	        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
1035	    }
1036	
1037	    /**
1038	     Check if a URL attribute should be normalized to an absolute URL in the cleaned output. Uses the configured
1039	     protocols for that tag+attribute pair, falling back to {@code :all} only if the tag does not define the
1040	     attribute.
1041	     */
1042	    boolean shouldAbsUrl(String tagName, String attrKey) {
1043	        if (preserveRelativeLinks) return false;
1044	        return shouldAbsUrl(TagName.valueOf(tagName), AttributeKey.valueOf(attrKey));
1045	    }
1046	
1047	    private boolean shouldAbsUrl(TagName tag, AttributeKey key) {
1048	        Set<AttributeKey> allowedAttrs = attributes.get(tag);
1049	        if (allowedAttrs != null && allowedAttrs.contains(key)) {
1050	            Map<AttributeKey, Set<Protocol>> protocolsByAttr = protocols.get(tag);
1051	            return protocolsByAttr != null && protocolsByAttr.containsKey(key);
1052	        }
1053	
1054	        Map<AttributeKey, AttributeValue> enforcedAttrs = enforcedAttributes.get(tag);
1055	        if (enforcedAttrs != null && enforcedAttrs.containsKey(key)) return false;
1056	
1057	        return !tag.equals(AllTag) && shouldAbsUrl(AllTag, key);
1058	    }
1059	
1060	    private static boolean isValidAnchor(String value) {
1061	        return value.startsWith("#") && !value.matches(".*\\s.*");
1062	    }
1063	
1064	    /**
1065	     Gets the Attributes that should be enforced for a given tag
1066	     * @param tagName the tag
1067	     * @return the attributes that will be enforced; empty if none are set for the given tag
1068	     */
1069	    public Attributes getEnforcedAttributes(String tagName) {
1070	        Attributes attrs = new Attributes();
1071	        TagName tag = TagName.valueOf(tagName);
1072	        if (enforcedAttributes.containsKey(tag)) {
1073	            Map<AttributeKey, AttributeValue> keyVals = enforcedAttributes.get(tag);
1074	            for (Map.Entry<AttributeKey, AttributeValue> entry : keyVals.entrySet()) {
1075	                attrs.put(entry.getKey().toString(), entry.getValue().toString());
1076	            }
1077	        }
1078	        return attrs;
1079	    }
1080	    
1081	    // named types for config. All just hold strings, but here for my sanity.
1082	
1083	    static class TagName extends TypedValue {
1084	        TagName(String value) {
1085	            super(value);
1086	        }
1087	
1088	        static TagName valueOf(String value) {
1089	            return new TagName(Normalizer.lowerCase(value));
1090	        }
1091	    }
1092	
1093	    static class AttributeKey extends TypedValue {
1094	        AttributeKey(String value) {
1095	            super(value);
1096	        }
1097	
1098	        static AttributeKey valueOf(String value) {
1099	            return new AttributeKey(Normalizer.lowerCase(value));
1100	        }
1101	    }
1102	
1103	    static class AttributeValue extends TypedValue {
1104	        AttributeValue(String value) {
1105	            super(value);
1106	        }
1107	
1108	        static AttributeValue valueOf(String value) {
1109	            return new AttributeValue(value);
1110	        }
1111	    }
1112	
1113	    static class Protocol extends TypedValue {
1114	        Protocol(String value) {
1115	            super(value);
1116	        }
1117	
1118	        static Protocol valueOf(String value) {
1119	            return new Protocol(value);
1120	        }
1121	    }
1122	
1123	    abstract static class TypedValue {
1124	        private final String value;
1125	
1126	        TypedValue(String value) {
1127	            Validate.notNull(value);
1128	            this.value = value;
1129	        }
1130	
1131	        @Override
1132	        public int hashCode() {
1133	            return value.hashCode();
1134	        }
1135	
1136	        @Override
1137	        public boolean equals(Object obj) {
1138	            if (this == obj) return true;
1139	            if (obj == null || getClass() != obj.getClass()) return false;
1140	            TypedValue other = (TypedValue) obj;
1141	            return Objects.equals(value, other.value);
1142	        }
1143	
1144	        @Override
1145	        public String toString() {
1146	            return value;
1147	        }
1148	    }
1149	}
