287	    @Test void activeDataUrlRejectedEvenWhenDataProtocolConfigured() {
288	        Safelist safelist = styleSafelist().addProtocols(":all", "style", "data");
289	        assertEquals("<div>x</div>",
290	            clean("<div style=\"background:url(data:image/svg+xml;base64,PHNjcmlwdD4=)\">x</div>", Base, safelist));
291	        assertEquals("<div>x</div>",
292	            clean("<div style=\"background:url(data:text/html,<script>)\" >x</div>", Base, safelist));
293	    }
