296	        assertEquals("<div style=\"color:red;color:blue\">x</div>",
297	            clean("<div style=\"color:red;font-family:'oops;color:blue\">x</div>")); // unclosed quote, recovers at ';'
298	        assertEquals("<div style=\"color:red;color:blue\">x</div>",
299	            clean("<div style=\"color:red;background:url(x.png;color:blue\">x</div>")); // unclosed function
300	        assertEquals("<div style=\"color:red;color:blue\">x</div>",
301	            clean("<div style=\"color:red;;;color:blue\">x</div>")); // repeated separators
302	        assertEquals("<div style=\"color:blue\">x</div>",
