package org.jsoup.safety;

import org.jsoup.internal.StringUtil;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;

import java.util.ArrayList;
import java.util.List;

/**
 Parses and sanitizes the text of an allowed {@code <style>} element, one stylesheet rule at a time. Like
 {@link StyleCleaner}, it is a small hand scanner rather than a full CSS parser: the sheet is split into qualified
 rules ({@code selector { declarations }}) and at-rules ({@code @media …}, {@code @import …}) while tracking the
 actual nesting of strings, parentheses, block comments, and CSS backslash escapes, so punctuation inside strings,
 functions, or comments cannot break out of its rule or declaration.

 <p>Selectors, ordinary declaration names and values (numbers, colors, fonts, custom properties), whitespace, and
 duplicates are emitted verbatim in source order. {@code @import} references, every {@code url(…)} argument
 (including one nested inside another function), and the legacy {@code expression(…)} function are checked with the
 same URL policy and the same obfuscation handling (mixed case, HTML entities, percent-encoding, control bytes, and
 CSS escapes) as an inline {@code style} attribute. Because the HTML parser keeps {@code <style>} contents as raw
 text, HTML entities are decoded only on the validation copy; the surviving text keeps its original spelling.</p>

 <p>A rejected import or declaration takes only itself; its rule's surviving selectors and declarations are kept,
 and no safe content in the same rule is lost. Unclosed strings, parentheses, or comments, repeated separators, and
 truncated imports and nested references never throw: rules whose boundaries can still be determined are handled
 independently, and only the unbounded or undecidable fragment is discarded. When every rule is invalid the whole
 stylesheet text is empty, in which case the caller removes the {@code <style>} element.</p>

 <p>The cleaner is stateless and thread-safe; all per-sheet state lives on the local parse stack.</p>
 */
final class StyleSheetCleaner {
    private final StyleCleaner sc;

    private StyleSheetCleaner(Safelist safelist, String tagName, Element el) {
        this.sc = StyleCleaner.create(safelist, tagName, el);
    }

    /**
     Cleans the raw text of an allowed {@code <style>} element rule by rule, preserving the order and original
     spelling of every rule, declaration, and value that survives.
     @return the cleaned stylesheet text, or {@code null} when no rule survives (in which case the element is removed)
     */
    static String clean(Safelist safelist, String tagName, Element el, String css) {
        return new StyleSheetCleaner(safelist, tagName, el).clean(css);
    }

    private String clean(String css) {
        int length = css.length();
        if (StringUtil.isBlank(css)) return css; // no rules at all: keep the element as-is

        // the parser hands <style> contents over verbatim, so HTML entities are decoded only for the safety checks;
        // a mapping back into the source keeps every surviving fragment at its original spelling
        String check = Parser.unescapeEntities(css, false);
        int[] srcMap = buildSourceMap(css, check);
        int[] match = sc.parenMatches(check);
        int[] opens = new int[check.length()];
        int parenDepth = 0;

        List<int[]> rules = new ArrayList<>(); // [start, end) of each rule worth emitting, in source coordinates
        int ruleStart = 0;
        int i = 0;
        while (i < length) {
            char c = check.charAt(i);
            if (c == '\\') { // CSS escape: the next code unit is literal, even '\{' or '\;'
                i += 2;
                continue;
            }
            if (c == '"' || c == '\'') {
                int[] quote = sc.scanQuoted(check, i + 1, c);
                i = quote[1] == 1 ? quote[0] + 1 : quote[0]; // recover at a newline or the next ';', else run to EOF
                continue;
            }
            if (c == '/' && i + 1 < length && check.charAt(i + 1) == '*') {
                int close = check.indexOf("*/", i + 2);
                i = close < 0 ? length : close + 2; // an unterminated comment is an unbounded tail, discarded below
                continue;
            }
            if (c == '(') {
                opens[parenDepth++] = i;
            } else if (c == ')') {
                if (parenDepth > 0) parenDepth--;
                // a stray ')' outside any function is ordinary separator text and never opens a block
            } else if (c == '{' && parenDepth == 0) {
                int close = matchingBrace(check, i + 1, length);
                int bodyStart = i + 1;
                int bodyEnd = close >= 0 ? close : length;
                int[] kept = cleanRuleBody(check, srcMap, bodyStart, bodyEnd, match, opens);
                if (kept != null) rules.add(kept);
                ruleStart = close >= 0 ? close + 1 : length;
                i = ruleStart;
                continue;
            } else if (c == ';' && parenDepth == 0) {
                int p = sc.skipSpaceAndComments(check, ruleStart, i);
                if (p >= 0 && p < i) { // a statement: an @import (or any statement) must pass on its own merits
                    int[] kept = cleanStatement(check, srcMap, ruleStart, i);
                    if (kept != null) rules.add(kept);
                }
                ruleStart = i + 1;
            }
            i++;
        }
        // trailing statement without a ';' (e.g. a final @import), and anything left after a stray '}'
        if (ruleStart < length) {
            int p = sc.skipSpaceAndComments(check, ruleStart, length);
            if (p >= 0 && p < length) {
                int[] kept = cleanStatement(check, srcMap, ruleStart, length);
                if (kept != null) rules.add(kept);
            }
        }
        if (rules.isEmpty()) return null;

        StringBuilder out = StringUtil.borrowBuilder();
        for (int[] rule : rules) {
            out.append(css, rule[0], rule[1]);
        }
        return StringUtil.releaseBuilder(out);
    }

    /**
     Cleans one qualified-rule body. The selector text and braces are copied by the caller from the source; here the
     declarations are validated independently and joined with semicolons, keeping only the declarations (and their
     in-value whitespace and comments) that survive. Leading/trailing whitespace and comments inside the body are
     formatting only and are not emitted around the surviving declarations.
     @return {@code [start, end)} source coordinates of the span of surviving declarations, or {@code null}
     */
    private int[] cleanRuleBody(String check, int[] srcMap, int bodyStart, int bodyEnd, int[] match, int[] opens) {
        int[] kept = cleanDeclarations(check, srcMap, bodyStart, bodyEnd, match, opens);
        return kept.length == 0 ? null : new int[] {kept[0], kept[kept.length - 1]};
    }

    /**
     Validates a top-level statement (an {@code @import} reference, or any other at-rule prelude such as
     {@code @charset} or {@code @namespace}) between semicolons. A statement whose only content is comments or
     whitespace is dropped as empty; an {@code @import} or any reference it carries must pass the URL policy.
     */
    private int[] cleanStatement(String check, int[] srcMap, int start, int end) {
        int p = sc.skipSpaceAndComments(check, start, end);
        if (p < 0 || p >= end) return null; // an unterminated comment makes the statement unbounded
        int q = end;
        while (q > p && StyleCleaner.isCssSpace(check.charAt(q - 1))) q--;
        if (p == q) return null;
        boolean safe;
        if (check.charAt(p) == '@') {
            int after = scanAtRuleName(check, p, q);
            String name = check.substring(p + 1, after);
            if (name.equalsIgnoreCase("import")) {
                safe = sc.isSafeImportDeclaration(check, p, q);
            } else {
                // other statements (@charset, @namespace, an unknown prelude, or ordinary free text): only their
                // references decide their fate, exactly like a custom-property value
                safe = sc.referencesAreSafe(check, p, q);
            }
        } else {
            safe = sc.referencesAreSafe(check, p, q);
        }
        return safe ? new int[] {toSource(srcMap, start), toSource(srcMap, q)} : null;
    }

    /**
     Splits the span into declarations on top-level semicolons (tracking strings, comments, escapes, and balanced
     functions) and validates each one independently, mirroring {@link StyleCleaner}'s inline split. Surviving
     declarations are returned as {@code [start, end)} source-coordinate spans, in original order; a declaration
     with a bad-string token, an unclosed function, or a failed reference check is dropped alone.
     */
    private int[] cleanDeclarations(String check, int[] srcMap, int start, int end, int[] match, int[] opens) {
        List<int[]> kept = new ArrayList<>();
        int segStart = start;
        int parenDepth = 0;
        boolean segmentBad = false;
        int length = end;
        int i = start;
        while (i < length) {
            char c = check.charAt(i);
            if (c == '\\') { i += 2; continue; }
            if (c == '"' || c == '\'') {
                int[] quote = sc.scanQuoted(check, i + 1, c);
                if (quote[1] == 1) {
                    i = quote[0] + 1;
                } else {
                    segmentBad = true; // a bad-string token makes only this declaration malformed
                    i = quote[1] == 2 ? quote[0] + 1 : quote[0]; // recover at the newline, or at the next ';'
                }
                continue;
            }
            if (c == '/' && i + 1 < length && check.charAt(i + 1) == '*') {
                int close = check.indexOf("*/", i + 2);
                if (close < 0 || close >= end) {
                    // an unterminated comment cannot be bounded and so invalidates only its own fragment: recover at
                    // the next ';' so that following declarations stay independently parseable
                    int semi = check.indexOf(';', i + 2);
                    if (semi < 0 || semi >= end) {
                        addSafeDeclaration(kept, check, srcMap, segStart, i, segmentBad || parenDepth != 0);
                        segStart = end;
                        break;
                    }
                    segmentBad = true;
                    i = semi; // the ';' branch ends the malformed fragment and resets for the next declaration
                    continue;
                }
                i = close + 2;
                continue;
            }
            if (c == '(') {
                opens[parenDepth++] = i;
            } else if (c == ')') {
                if (parenDepth > 0) parenDepth--;
                else segmentBad = true; // a stray ')' makes this declaration malformed
            } else if (c == ';') {
                if (parenDepth > 0 && match[opens[parenDepth - 1]] >= 0 && match[opens[parenDepth - 1]] < end) {
                    i++; // the ';' is content of a function that closes later (e.g. an unquoted data: URL)
                    continue;
                }
                addSafeDeclaration(kept, check, srcMap, segStart, i, segmentBad || parenDepth != 0);
                segStart = i + 1;
                segmentBad = false;
                parenDepth = 0;
            }
            i++;
        }
        if (segStart < end) addSafeDeclaration(kept, check, srcMap, segStart, end, segmentBad || parenDepth != 0);

        int[] spans = new int[kept.size() * 2];
        for (int k = 0; k < kept.size(); k++) {
            spans[k * 2] = kept.get(k)[0];
            spans[k * 2 + 1] = kept.get(k)[1];
        }
        return spans;
    }

    /** Validates one declaration and records its source span when it survives. */
    private void addSafeDeclaration(List<int[]> kept, String check, int[] srcMap, int start, int end, boolean bad) {
        int to = sc.safeDeclarationRange(check, start, end, bad);
        if (to > start) kept.add(new int[] {toSource(srcMap, start), toSource(srcMap, to)});
    }

    /** Finds the '}' that closes a block, skipping strings, comments, escapes, and nested braces. */
    private static int matchingBrace(String value, int from, int end) {
        int depth = 1;
        int i = from;
        while (i < end) {
            char c = value.charAt(i);
            if (c == '\\') { i += 2; continue; }
            if (c == '"' || c == '\'') {
                int[] quote = scScanQuoted(value, i + 1, c);
                i = quote[1] == 0 ? quote[0] : quote[0] + 1; // recover at the next ';'/newline, or past a closed quote
                continue;
            }
            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
                int close = value.indexOf("*/", i + 2);
                if (close < 0) return -1;
                i = close + 2;
                continue;
            }
            if (c == '{') depth++;
            else if (c == '}') { depth--; if (depth == 0) return i; }
            i++;
        }
        return -1;
    }

    // scanQuoted is an instance method on StyleCleaner; this static bridge keeps matchingBrace itself static
    private static int[] scScanQuoted(String value, int from, char quote) {
        return new StyleSheetCleaner(null, null, null).sc.scanQuoted(value, from, quote);
    }

    /** Reads the name run following an '@' (import, media, charset, …), with no escape handling for the prelude. */
    private int scanAtRuleName(String value, int at, int end) {
        int i = at + 1;
        while (i < end) {
            char c = value.charAt(i);
            if (Character.isLetterOrDigit(c) || c == '-' || c == '_') i++;
            else break;
        }
        return i;
    }

    /**
     Builds the map from offsets in the entity-decoded validation text back to offsets in the raw {@code <style>}
     text. A decoded run that replaced a longer entity (e.g. {@code &#106;} → {@code j}) maps every decoded offset
     to the start of the entity, so a surviving span is copied from the source and keeps its original spelling.
     */
    private static int[] buildSourceMap(String raw, String decoded) {
        int dlen = decoded.length();
        int[] map = new int[dlen + 1];
        int r = 0;
        int d = 0;
        while (d < dlen) {
            if (r < raw.length() && raw.charAt(r) == '&') {
                int semi = raw.indexOf(';', r + 1);
                if (semi > r && semi - r <= 32) { // named and numeric entities are short; a far ';' is ordinary text
                    String ent = Parser.unescapeEntities(raw.substring(r, semi + 1), false);
                    if (!ent.equals(raw.substring(r, semi + 1))) {
                        for (int k = 0; k < ent.length(); k++) map[d + k] = r;
                        map[d + ent.length()] = semi + 1;
                        d += ent.length();
                        r = semi + 1;
                        continue;
                    }
                }
            }
            map[d] = r;
            d++;
            r++;
        }
        while (d <= dlen) map[d++] = Math.min(r, raw.length());
        return map;
    }

    /** Maps an offset in the decoded validation text to the same anchor in the raw source text. */
    private static int toSource(int[] srcMap, int decodedOffset) {
        if (decodedOffset <= 0) return 0;
        if (decodedOffset >= srcMap.length) return srcMap[srcMap.length - 1];
        return srcMap[decodedOffset];
    }
}

