            spans[k * 2 + 1] = kept.get(k)[1];
        }
        return spans;
    }

    /** Validates one declaration and records its source span when it survives. */
    private void addSafeDeclaration(List<int[]> kept, String check, int[] srcMap, int start, int end, boolean bad) {
        int to = sc.safeDeclarationRange(check, start, end, bad);
