    }

    // scanQuoted is an instance method on StyleCleaner; this static bridge keeps matchingBrace itself static
    private static int[] scScanQuoted(String value, int from, char quote) {
        return new StyleSheetCleaner(null, null, null).sc.scanQuoted(value, from, quote);
    }

    /** Reads the name run following an '@' (import, media, charset, …), with no escape handling for the prelude. */
    private int scanAtRuleName(String value, int at, int end) {
        int i = at + 1;
        while (i < end) {
            char c = value.charAt(i);
            if (Character.isLetterOrDigit(c) || c == '-' || c == '_') i++;
            else break;
        }
        return i;
    }

    /**
