     text. A decoded run that replaced a longer entity (e.g. {@code &#106;} → {@code j}) maps every decoded offset
     to the start of the entity, so a surviving span is copied from the source and keeps its original spelling.
     */
    private static int[] buildSourceMap(String raw, String decoded) {
        int dlen = decoded.length();
        int[] map = new int[dlen + 1];
        int r = 0;
        int d = 0;
        while (d < dlen) {
            if (r < raw.length() && raw.charAt(r) == '&') {
                int semi = raw.indexOf(';', r + 1);
                if (semi > r && semi - r <= 32) { // named and numeric entities are short; a far ';' is ordinary text
                    String ent = Parser.unescapeEntities(raw.substring(r, semi + 1), false);
                    if (!ent.equals(raw.substring(r, semi + 1))) {
                        for (int k = 0; k < ent.length(); k++) map[d + k] = r;
                        map[d + ent.length()] = semi + 1;
                        d += ent.length();
                        r = semi + 1;
                        continue;
                    }
                }
            }
            map[d] = r;
            d++;
            r++;
        }
        while (d <= dlen) map[d++] = Math.min(r, raw.length());
        return map;
    }

    /** Maps an offset in the decoded validation text to the same anchor in the raw source text. */
    private static int toSource(int[] srcMap, int decodedOffset) {
        if (decodedOffset <= 0) return 0;
        if (decodedOffset >= srcMap.length) return srcMap[srcMap.length - 1];
        return srcMap[decodedOffset];
    }
}

