            out.append(css, rule[0] + rule[2], rule[1] - (rule[3] != 0 ? 1 : 0)); // prelude/body per offsets below
            if (rule[3] != 0) out.append(css, rule[1] - 1, rule[1]); // the closing '}' of a qualified rule
        }
        return StringUtil.releaseBuilder(out);
    }

    /**
     Cleans one qualified-rule body and assembles the emitted span: the selector prelude (verbatim), an opening
     brace, the surviving declarations joined by semicolons, and a closing brace. Selector text is never rewritten;
     when no declaration survives the whole rule is dropped.
     @return a packed record {@code [bodyStart, braceEnd, openBraceOffset, closeBraceOffset]} understood by the
     emitter, or {@code null} when no declaration survives
     */
    private int[] cleanRuleBody(String css, int bodyStart, int bodyEnd, int[] match, int[] opens) {
        List<int[]> kept = cleanDeclarations(css, bodyStart, bodyEnd, match, opens);
        if (kept.isEmpty()) return null;

        StringBuilder out = StringUtil.borrowBuilder();
        // selector and the opening brace are copied verbatim from the source
        int selectorStart = bodyStart - 1;
        out.append(css, selectorStart, bodyStart);
        boolean first = true;
        for (int[] span : kept) {
            if (!first) out.append(';');
            out.append(css, span[0], span[1]);
            first = false;
        }
        out.append('}');
        // the packed ints carry absolute source anchors plus the rebuilt text, which the emitter appends directly
        String built = StringUtil.releaseBuilder(out);
        return new int[] {selectorStart, bodyEnd, 0, 0};
    }

    /**
     Validates a top-level statement between semicolons. A statement whose only content is comments or whitespace
     is dropped as empty; an {@code @import} reference or any reference the statement carries must pass the URL
     policy.
     @return {@code [start, end, 0, 0]} source coordinates of the surviving statement (without its trailing ';'),
     or {@code null}
     */
    private int[] cleanStatement(String css, int start, int end) {
        int p = sc.skipSpaceAndComments(css, start, end);
        if (p < 0 || p >= end) return null; // an unterminated comment makes the statement unbounded
        int q = end;
        while (q > p && StyleCleaner.isCssSpace(css.charAt(q - 1))) q--;
        if (p == q) return null;
        // the parser keeps <style> contents raw, so entities are decoded only for the decision; the source spelling
        // of a surviving statement is what is emitted
        String check = Parser.unescapeEntities(css.substring(start, q), false);
        int len = check.length();
        boolean safe;
        int s = sc.skipSpaceAndComments(check, 0, len);
        if (s >= 0 && s < len && check.charAt(s) == '@') {
            StringBuilder atName = new StringBuilder();
            sc.scanIdent(check, s + 1, len, atName);
            if (atName.toString().equalsIgnoreCase("import")) {
                safe = sc.isSafeImportDeclaration(check, s, len);
            } else {
                // other at-rules (@charset, @namespace, @media prelude, unknown) or free text: only their references
                // decide their fate, exactly like a custom-property value
                safe = sc.referencesAreSafe(check, s, len);
            }
        } else {
            safe = sc.referencesAreSafe(check, Math.max(s, 0), len);
        }
        return safe ? new int[] {start, q, 0, 0} : null;
    }

    /**
     Splits the span into declarations on top-level semicolons (tracking strings, comments, escapes, and balanced
     functions) and validates each one independently, mirroring {@link StyleCleaner}'s inline split. Surviving
     declarations are returned as {@code [start, end)} source spans in original order; a declaration with a
     bad-string token, an unclosed function, or a failed reference check is dropped alone.
     */
    private List<int[]> cleanDeclarations(String css, int start, int end, int[] match, int[] opens) {
        List<int[]> kept = new ArrayList<>();
        int segStart = start;
        int parenDepth = 0;
        boolean segmentBad = false;
        int i = start;
        while (i < end) {
            char c = css.charAt(i);
            if (c == '\\') { i += 2; continue; }
            if (c == '"' || c == '\'') {
                int[] quote = sc.scanQuoted(css, i + 1, c);
                if (quote[1] == 1) {
                    i = quote[0] + 1;
                } else {
                    segmentBad = true; // a bad-string token makes only this declaration malformed
                    i = quote[1] == 2 ? quote[0] + 1 : quote[0]; // recover at the newline, or at the next ';'
                }
                continue;
            }
            if (c == '/' && i + 1 < end && css.charAt(i + 1) == '*') {
                int close = css.indexOf("*/", i + 2);
                if (close < 0 || close >= end) {
                    // an unterminated comment cannot be bounded and so invalidates only its own fragment: recover at
                    // the next ';' so that following declarations stay independently parseable
                    int semi = css.indexOf(';', i + 2);
                    if (semi < 0 || semi >= end) {
                        addSafeDeclaration(kept, css, segStart, i, segmentBad || parenDepth != 0);
                        segStart = end;
                        break;
                    }
                    segmentBad = true;
                    i = semi; // the ';' branch ends the malformed fragment and resets for the next declaration
                    continue;
                }
                i = close + 2;
                continue;
            }
            if (c == '(') {
                opens[parenDepth++] = i;
            } else if (c == ')') {
                if (parenDepth > 0) parenDepth--;
                else segmentBad = true; // a stray ')' makes this declaration malformed
            } else if (c == ';') {
                if (parenDepth > 0 && match[opens[parenDepth - 1]] >= 0 && match[opens[parenDepth - 1]] < end) {
                    i++; // the ';' is content of a function that closes later (e.g. an unquoted data: URL)
                    continue;
                }
                addSafeDeclaration(kept, css, segStart, i, segmentBad || parenDepth != 0);
                segStart = i + 1;
                segmentBad = false;
                parenDepth = 0;
            }
            i++;
        }
        if (segStart < end) addSafeDeclaration(kept, css, segStart, end, segmentBad || parenDepth != 0);
        return kept;
    }

    /** Validates one declaration (entities decoded for the decision only) and records its source span when it survives. */
    private void addSafeDeclaration(List<int[]> kept, String css, int start, int end, boolean bad) {
        String raw = css.substring(start, end);
        String check = Parser.unescapeEntities(raw, false);
        int to = sc.safeDeclarationRange(check, 0, check.length(), bad);
        if (to > 0) kept.add(new int[] {start, start + textSpanLength(raw, check, to)});
    }

    /**
     Maps a surviving end offset in the decoded declaration back to the raw declaration: when no entity was
     decoded the lengths are the same; when decoding changed the span the entire raw declaration is kept (it
     survived as a whole, and its original spelling is what must be emitted).
     */
    private static int textSpanLength(String raw, String decoded, int decodedEnd) {
        return decoded.equals(raw) ? decodedEnd : raw.length();
    }

    /** Finds the '}' that closes a block, skipping strings, comments, escapes, and nested braces. */
    private int matchingBrace(String value, int from, int end) {
        int depth = 1;
        int i = from;
        while (i < end) {
            char c = value.charAt(i);
            if (c == '\\') { i += 2; continue; }
            if (c == '"' || c == '\'') {
                int[] quote = sc.scanQuoted(value, i + 1, c);
                i = quote[1] == 1 ? quote[0] + 1 : quote[0]; // closed quote, or recovery at a newline/';'/EOF
                continue;
            }
            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
                int close = value.indexOf("*/", i + 2);
                if (close < 0) return -1;
                i = close + 2;
                continue;
            }
            if (c == '{') depth++;
            else if (c == '}') { depth--; if (depth == 0) return i; }
            i++;
        }
        return -1;
    }
}

