package org.jsoup.safety;

import org.jsoup.internal.StringUtil;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;

import java.util.ArrayList;
import java.util.List;

/**
 Parses and sanitizes the text of an allowed {@code <style>} element, one stylesheet rule at a time. Like
 {@link StyleCleaner}, it is a small hand scanner rather than a full CSS parser: the sheet is split into qualified
 rules ({@code selector { declarations }}) and statements ({@code @import …}, {@code @media …}) while tracking the
 actual nesting of strings, parentheses, block comments, and CSS backslash escapes, so punctuation inside strings,
 functions, or comments cannot break out of its rule or declaration. Nested blocks (rules inside an
 {@code @media}/{@code @supports} block) are handled recursively and independently.

 <p>Selectors, at-rule preludes, ordinary declaration names and values (numbers, colors, fonts, custom
 properties), whitespace, comments, and duplicates are emitted verbatim in source order. {@code @import}
 references, every {@code url(…)} argument (including one nested inside another function), and the legacy
 {@code expression(…)} function are checked with the same URL policy and the same obfuscation handling (mixed
 case, HTML entities, percent-encoding, control bytes, and CSS escapes) as an inline {@code style} attribute. The
 HTML parser keeps {@code <style>} contents as raw text and never applies HTML entities to it, so rule and
 declaration boundaries are always scanned in the raw text (an entity such as {@code &#123;} cannot forge a block
 boundary), while entities within an already bounded statement or declaration are decoded only for the safety
 decision; a surviving fragment always keeps its original spelling.</p>

 <p>A rejected import or declaration takes only itself; its rule's surviving selectors and declarations are kept,
 and no safe content in the same rule is lost. Unclosed strings, parentheses, or comments, repeated separators, and
 truncated imports and nested references never throw: rules whose boundaries can still be determined are handled
 independently, and only the unbounded or undecidable fragment is discarded. When no rule survives the result is
 empty, in which case the caller removes the {@code <style>} element.</p>

 <p>The cleaner is stateless and thread-safe; all per-sheet state lives on the local parse stack.</p>
 */
final class StyleSheetCleaner {
    private static final int MaxNesting = 256; // bound recursion on deliberately or accidentally deep nesting

    private final StyleCleaner sc;
    private int[] parenMatch; // index of each parenthesis's mate in the raw sheet, or -1 when unmatched
    private int[] opens; // positions of the currently open parentheses while splitting declarations

    private StyleSheetCleaner(Safelist safelist, String tagName, Element el) {
        this.sc = StyleCleaner.create(safelist, tagName, el);
    }

    /**
     Cleans the raw text of an allowed {@code <style>} element rule by rule, preserving the order and original
     spelling of every rule, declaration, and value that survives.
     @return the cleaned stylesheet text, or {@code null} when no rule survives (in which case the element is removed)
     */
    static String clean(Safelist safelist, String tagName, Element el, String css) {
        return new StyleSheetCleaner(safelist, tagName, el).cleanSheet(css);
    }

    private String cleanSheet(String css) {
        if (StringUtil.isBlank(css)) return css; // no rules at all: keep the element as-is
        parenMatch = sc.parenMatches(css);
        opens = new int[css.length()];
        StringBuilder out = StringUtil.borrowBuilder();
        process(css, 0, css.length(), 0, out);
        return out.length() == 0 ? null : StringUtil.releaseBuilder(out);
    }

    /**
     Walks one stylesheet scope (the whole sheet, or an at-rule block) and appends every surviving statement and
     rule to {@code out} in source order.
     */
    private void process(String css, int start, int end, int depth, StringBuilder out) {
        int length = end;
        int ruleStart = start;
        int parenDepth = 0;
        int i = start;
        while (i < length) {
            char c = css.charAt(i);
            if (c == '\\') { // CSS escape: the next code unit is literal, even '\{' or '\;'
                i += 2;
                continue;
            }
            if (c == '"' || c == '\'') {
                int[] quote = sc.scanQuoted(css, i + 1, c);
                i = quote[1] == 1 ? quote[0] + 1 : quote[0]; // recover at a newline/';', else run to EOF
                continue;
            }
            if (c == '/' && i + 1 < length && css.charAt(i + 1) == '*') {
                int close = css.indexOf("*/", i + 2);
                i = close < 0 ? length : close + 2; // an unterminated comment is an unbounded tail, discarded below
                continue;
            }
            if (c == '(') {
                parenDepth++;
            } else if (c == ')' && parenDepth > 0) {
                parenDepth--; // a stray ')' outside any function is ordinary separator text
            } else if ((c == '{' || c == '}') && parenDepth == 0) {
                if (c == '{') {
                    int close = matchingBrace(css, i + 1, length);
                    int bodyEnd = close >= 0 ? close : length;
                    emitRule(css, ruleStart, i, bodyEnd, close >= 0, depth, out);
                    ruleStart = close >= 0 ? close + 1 : length;
                    i = ruleStart;
                    continue;
                }
                // a stray '}' closes no block we opened: treat the prelude before it as a standalone statement
                emitStatement(css, ruleStart, i, out);
                ruleStart = i + 1;
            } else if (c == ';' && parenDepth == 0) {
                emitStatement(css, ruleStart, i, out);
                ruleStart = i + 1;
            }
            i++;
        }
        if (ruleStart < length) emitStatement(css, ruleStart, length, out); // a trailing statement without ';'
    }

    /**
     Validates and emits one qualified rule (or at-rule block): the prelude is copied verbatim when it carries no
     unsafe reference, and the block is emitted only when its body yields surviving content. Nested blocks are
     processed into their own buffer first, so an empty body never leaves an empty rule behind.
     */
    private void emitRule(String css, int preludeStart, int brace, int bodyEnd, boolean closed, int depth,
                          StringBuilder out) {
        if (!preludeIsSafe(css, preludeStart, brace)) return;
        StringBuilder body = StringUtil.borrowBuilder();
        if (depth < MaxNesting) process(css, brace + 1, bodyEnd, depth + 1, body);
        if (body.length() == 0) {
            StringUtil.releaseBuilderVoid(body);
            return;
        }
        out.append(css, preludeStart, brace + 1); // selector/at-rule prelude and the opening brace, verbatim
        out.append(body);
        StringUtil.releaseBuilderVoid(body);
        if (closed) out.append('}');
    }

    /** A selector/at-rule prelude is inert text except for an actual reference it may carry. */
    private boolean preludeIsSafe(String css, int start, int end) {
        int p = sc.skipSpaceAndComments(css, start, end);
        if (p < 0) return false; // an unterminated comment in the prelude makes the rule unbounded
        if (p >= end) return false; // an empty prelude (e.g. a stray '{') is not a rule
        String check = decode(css, p, end);
        int len = check.length();
        int s = sc.skipSpaceAndComments(check, 0, len);
        if (s < 0) return false;
        return sc.referencesAreSafe(check, s, len);
    }

    /**
     Validates and emits one top-level statement between separators. Whitespace- or comment-only fragments are
     skipped; an {@code @import}'s reference must pass the URL rules, any other statement passes when its own
     references pass. The trailing semicolon is re-emitted so adjacent statements never join.
     */
    private void emitStatement(String css, int start, int end, StringBuilder out) {
        int p = sc.skipSpaceAndComments(css, start, end);
        if (p < 0 || p >= end) return; // an unterminated comment makes the statement unbounded
        int q = end;
        while (q > p && StyleCleaner.isCssSpace(css.charAt(q - 1))) q--;
        if (p == q) return;
        String check = decode(css, start, q); // entities are decoded only for the decision
        int len = check.length();
        int s = sc.skipSpaceAndComments(check, 0, len);
        if (s < 0 || s >= len) return;
        boolean safe;
        if (check.charAt(s) == '@') {
            StringBuilder atName = new StringBuilder();
            sc.scanIdent(check, s + 1, len, atName);
            if (atName.toString().equalsIgnoreCase("import")) {
                safe = sc.isSafeImportDeclaration(check, s, len);
            } else {
                // other at-rules (@charset, @namespace, an unknown prelude) or their references decide their fate
                safe = sc.referencesAreSafe(check, s, len);
            }
        } else {
            safe = sc.referencesAreSafe(check, s, len);
        }
        if (safe) out.append(css, start, q).append(';');
    }

    /** Decodes HTML entities in one already bounded span, used only for a safety decision on raw stylesheet text. */
    private static String decode(String css, int start, int end) {
        String raw = css.substring(start, end);
        return raw.indexOf('&') >= 0 ? Parser.unescapeEntities(raw, false) : raw;
    }

    /**
     Splits a rule body into declarations on top-level semicolons (tracking strings, comments, escapes, and
     balanced functions) and appends each surviving declaration to {@code body}, separated by semicolons, in
     source order. A declaration with a bad-string token, an unclosed function, or a failed reference check is
     dropped alone.
     */
    private void appendDeclarations(String css, int start, int end, StringBuilder body) {
        List<int[]> kept = new ArrayList<>();
        int segStart = start;
        int parenDepth = 0;
        boolean segmentBad = false;
        int i = start;
        while (i < end) {
            char c = css.charAt(i);
            if (c == '\\') { i += 2; continue; }
            if (c == '"' || c == '\'') {
                int[] quote = sc.scanQuoted(css, i + 1, c);
                if (quote[1] == 1) {
                    i = quote[0] + 1;
                } else {
                    segmentBad = true; // a bad-string token makes only this declaration malformed
                    i = quote[1] == 2 ? quote[0] + 1 : quote[0]; // recover at the newline, or at the next ';'
                }
                continue;
            }
            if (c == '/' && i + 1 < end && css.charAt(i + 1) == '*') {
                int close = css.indexOf("*/", i + 2);
                if (close < 0 || close >= end) {
                    // an unterminated comment cannot be bounded and so invalidates only its own fragment: recover at
                    // the next ';' so that following declarations stay independently parseable
                    int semi = css.indexOf(';', i + 2);
                    if (semi < 0 || semi >= end) {
                        addSafeDeclaration(kept, css, segStart, i, segmentBad || parenDepth != 0);
                        segStart = end;
                        break;
                    }
                    segmentBad = true;
                    i = semi; // the ';' branch ends the malformed fragment and resets for the next declaration
                    continue;
                }
                i = close + 2;
                continue;
            }
            if (c == '(') {
                opens[parenDepth++] = i;
            } else if (c == ')') {
                if (parenDepth > 0) parenDepth--;
                else segmentBad = true; // a stray ')' makes this declaration malformed
            } else if (c == ';') {
                if (parenDepth > 0 && parenMatch[opens[parenDepth - 1]] >= 0 && parenMatch[opens[parenDepth - 1]] < end) {
                    i++; // the ';' is content of a function that closes later (e.g. an unquoted data: URL)
                    continue;
                }
                addSafeDeclaration(kept, css, segStart, i, segmentBad || parenDepth != 0);
                segStart = i + 1;
                segmentBad = false;
                parenDepth = 0;
            }
            i++;
        }
        if (segStart < end) addSafeDeclaration(kept, css, segStart, end, segmentBad || parenDepth != 0);
        for (int k = 0; k < kept.size(); k++) {
            if (k > 0) body.append(';');
            body.append(css, kept.get(k)[0], kept.get(k)[1]);
        }
    }

    /** Validates one declaration (entities decoded for the decision only) and records its source span when it survives. */
    private void addSafeDeclaration(List<int[]> kept, String css, int start, int end, boolean bad) {
        String raw = css.substring(start, end);
        String check = raw.indexOf('&') >= 0 ? Parser.unescapeEntities(raw, false) : raw;
        int to = sc.safeDeclarationRange(check, 0, check.length(), bad);
        if (to <= 0) return;
        // with no decoded entity the offsets line up; with an entity anywhere, the declaration survives as a whole
        // and keeps its full original spelling (safeDeclarationRange only ever returns the trimmed end or nothing)
        int spanEnd = check == raw ? start + to : end;
        kept.add(new int[] {start, spanEnd});
    }

    /** Finds the '}' that closes a block, skipping strings, comments, escapes, and nested braces. */
    private int matchingBrace(String value, int from, int end) {
        int depth = 1;
        int i = from;
        while (i < end) {
            char c = value.charAt(i);
            if (c == '\\') { i += 2; continue; }
            if (c == '"' || c == '\'') {
                int[] quote = sc.scanQuoted(value, i + 1, c);
                i = quote[1] == 1 ? quote[0] + 1 : quote[0]; // closed quote, or recovery at a newline/';'/EOF
                continue;
            }
            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
                int close = value.indexOf("*/", i + 2);
                if (close < 0) return -1;
                i = close + 2;
                continue;
            }
            if (c == '{') depth++;
            else if (c == '}') { depth--; if (depth == 0) return i; }
            i++;
        }
        return -1;
    }
}

