                          StringBuilder out) {
        if (!preludeIsSafe(css, preludeStart, brace)) return;
        StringBuilder body = StringUtil.borrowBuilder();
        if (depth < MaxNesting) process(css, brace + 1, bodyEnd, depth + 1, body);
        if (body.length() == 0) {
            StringUtil.releaseBuilderVoid(body);
            return;
        }
        out.append(css, preludeStart, brace + 1); // selector/at-rule prelude and the opening brace, verbatim
        out.append(body);
        StringUtil.releaseBuilderVoid(body);
        if (closed) out.append('}');
