    /** A selector/at-rule prelude is inert text except for an actual reference it may carry. */
    private boolean preludeIsSafe(String css, int start, int end) {
        int p = sc.skipSpaceAndComments(css, start, end);
        if (p < 0) return false; // an unterminated comment in the prelude makes the rule unbounded
        if (p >= end) return false; // an empty prelude (e.g. a stray '{') is not a rule
        String check = decode(css, p, end);
        int len = check.length();
        int s = sc.skipSpaceAndComments(check, 0, len);
        if (s < 0) return false;
        return sc.referencesAreSafe(check, s, len);
    }

    /**
     Validates and emits one top-level statement between separators. Whitespace- or comment-only fragments are
     skipped; an {@code @import}'s reference must pass the URL rules, any other statement passes when its own
     references pass. The trailing semicolon is re-emitted so adjacent statements never join.
     */
    private void emitStatement(String css, int start, int end, StringBuilder out) {
        int p = sc.skipSpaceAndComments(css, start, end);
        if (p < 0 || p >= end) return; // an unterminated comment makes the statement unbounded
        int q = end;
        while (q > p && StyleCleaner.isCssSpace(css.charAt(q - 1))) q--;
        if (p == q) return;
        String check = decode(css, start, q); // entities are decoded only for the decision
        int len = check.length();
        int s = sc.skipSpaceAndComments(check, 0, len);
        if (s < 0 || s >= len) return;
        boolean safe;
        if (check.charAt(s) == '@') {
