    /** Decodes HTML entities in one already bounded span, used only for a safety decision on raw stylesheet text. */
    private static String decode(String css, int start, int end) {
        String raw = css.substring(start, end);
        return raw.indexOf('&') >= 0 ? Parser.unescapeEntities(raw, false) : raw;
    }

    /**
     Splits a rule body into declarations on top-level semicolons (tracking strings, comments, escapes, and
     balanced functions) and appends each surviving declaration to {@code body}, separated by semicolons, in
     source order. A declaration with a bad-string token, an unclosed function, or a failed reference check is
     dropped alone.
     */
    private void appendDeclarations(String css, int start, int end, StringBuilder body) {
        List<int[]> kept = new ArrayList<>();
        int segStart = start;
        int parenDepth = 0;
        boolean segmentBad = false;
        int i = start;
        while (i < end) {
            char c = css.charAt(i);
            if (c == '\\') { i += 2; continue; }
            if (c == '"' || c == '\'') {
                int[] quote = sc.scanQuoted(css, i + 1, c);
                if (quote[1] == 1) {
                    i = quote[0] + 1;
                } else {
                    segmentBad = true; // a bad-string token makes only this declaration malformed
                    i = quote[1] == 2 ? quote[0] + 1 : quote[0]; // recover at the newline, or at the next ';'
                }
                continue;
            }
            if (c == '/' && i + 1 < end && css.charAt(i + 1) == '*') {
                int close = css.indexOf("*/", i + 2);
                if (close < 0 || close >= end) {
                    // an unterminated comment cannot be bounded and so invalidates only its own fragment: recover at
                    // the next ';' so that following declarations stay independently parseable
                    int semi = css.indexOf(';', i + 2);
                    if (semi < 0 || semi >= end) {
                        addSafeDeclaration(kept, css, segStart, i, segmentBad || parenDepth != 0);
                        segStart = end;
                        break;
                    }
                    segmentBad = true;
                    i = semi; // the ';' branch ends the malformed fragment and resets for the next declaration
                    continue;
                }
                i = close + 2;
                continue;
            }
            if (c == '(') {
                opens[parenDepth++] = i;
            } else if (c == ')') {
                if (parenDepth > 0) parenDepth--;
                else segmentBad = true; // a stray ')' makes this declaration malformed
            } else if (c == ';') {
                if (parenDepth > 0 && parenMatch[opens[parenDepth - 1]] >= 0 && parenMatch[opens[parenDepth - 1]] < end) {
                    i++; // the ';' is content of a function that closes later (e.g. an unquoted data: URL)
                    continue;
                }
                addSafeDeclaration(kept, css, segStart, i, segmentBad || parenDepth != 0);
                segStart = i + 1;
                segmentBad = false;
                parenDepth = 0;
            }
            i++;
        }
        if (segStart < end) addSafeDeclaration(kept, css, segStart, end, segmentBad || parenDepth != 0);
        for (int k = 0; k < kept.size(); k++) {
            if (k > 0) body.append(';');
            body.append(css, kept.get(k)[0], kept.get(k)[1]);
        }
    }

    /** Validates one declaration (entities decoded for the decision only) and records its source span when it survives. */
    private void addSafeDeclaration(List<int[]> kept, String css, int start, int end, boolean bad) {
        String raw = css.substring(start, end);
        String check = raw.indexOf('&') >= 0 ? Parser.unescapeEntities(raw, false) : raw;
        int to = sc.safeDeclarationRange(check, 0, check.length(), bad);
        if (to <= 0) return;
        // with no decoded entity the offsets line up; with an entity anywhere, the declaration survives as a whole
        // and keeps its full original spelling (safeDeclarationRange only ever returns the trimmed end or nothing)
        int spanEnd = check == raw ? start + to : end;
        kept.add(new int[] {start, spanEnd});
    }

    /** Finds the '}' that closes a block, skipping strings, comments, escapes, and nested braces. */
    private int matchingBrace(String value, int from, int end) {
        int depth = 1;
        int i = from;
        while (i < end) {
            char c = value.charAt(i);
            if (c == '\\') { i += 2; continue; }
            if (c == '"' || c == '\'') {
                int[] quote = sc.scanQuoted(value, i + 1, c);
                i = quote[1] == 1 ? quote[0] + 1 : quote[0]; // closed quote, or recovery at a newline/';'/EOF
                continue;
            }
            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
                int close = value.indexOf("*/", i + 2);
                if (close < 0) return -1;
                i = close + 2;
                continue;
            }
            if (c == '{') depth++;
            else if (c == '}') { depth--; if (depth == 0) return i; }
            i++;
        }
        return -1;
    }
}

