private String cleanSheet(String css) {
    if (StringUtil.isBlank(css)) return css; // no rules at all: keep the element as-is
    StringBuilder out = StringUtil.borrowBuilder();
    process(css, 0, css.length(), 0, out);
    return out.length() == 0 ? null : StringUtil.releaseBuilder(out);
}

/**
 Walks one stylesheet scope (the whole sheet, or an at-rule block) and appends every surviving statement and
 rule to {@code out} in source order. Parenthesis matching is scoped to this span (a brace always bounds a
 block), so a semicolon stays function content only for a function that closes within the scope.
 */
private void process(String css, int start, int end, int depth, StringBuilder out) {
    int[] match = sc.parenMatches(css.substring(start, end)); // local coordinates; offset by start
    int[] opens = new int[end - start];
    int parenDepth = 0;
    int ruleStart = start;
    int i = start;
    while (i < end) {
        char c = css.charAt(i);
        if (c == '\\') { // CSS escape: the next code unit is literal, even '\{' or '\;'
            i += 2;
            continue;
        }
        if (c == '"' || c == '\'') {
            int[] quote = sc.scanQuoted(css, i + 1, c);
            i = quote[1] == 1 ? quote[0] + 1 : quote[0]; // recover at a newline/';', else run to EOF
            continue;
        }
        if (c == '/' && i + 1 < end && css.charAt(i + 1) == '*') {
            int close = css.indexOf("*/", i + 2);
            i = close < 0 ? end : close + 2; // an unterminated comment is an unbounded tail, discarded below
            continue;
        }
        if (c == '(') {
            opens[parenDepth++] = i - start;
        } else if (c == ')') {
            if (parenDepth > 0) parenDepth--; // a stray ')' outside any function is ordinary separator text
        } else if (c == '{') {
            int close = matchingBrace(css, i + 1, end);
            int bodyEnd = close >= 0 ? close : end;
            emitRule(css, ruleStart, i, bodyEnd, close >= 0, depth, out);
            parenDepth = 0; // braces always bound blocks; an unclosed function does not carry into the next rule
            ruleStart = close >= 0 ? close + 1 : end;
            i = ruleStart;
            continue;
        } else if (c == '}') {
            // a stray '}' closes no block opened in this scope: validate the prelude before it as a statement
            emitStatement(css, ruleStart, i, out);
            parenDepth = 0;
            ruleStart = i + 1;
        } else if (c == ';' && (parenDepth == 0 || match[opens[parenDepth - 1]] < 0)) {
            // a ';' ends the statement unless it is content of a function that closes later in this scope
            emitStatement(css, ruleStart, i, out);
            parenDepth = 0;
            ruleStart = i + 1;
        }
