import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.safety.*;

public class SheetProbe {
    static Safelist sl() {
        return Safelist.relaxed().addTags("style").addAttributes(":all","style");
    }
    static String clean(String css) {
        Document d = Jsoup.parseBodyFragment("<style>"+css+"</style><p>x</p>", "https://example.com/a/b");
        Document c = new Cleaner(sl()).clean(d);
        return c.body().selectFirst("style") == null ? "<style REMOVED>" : c.body().selectFirst("style").data();
    }
    public static void main(String[] a) {
        String[] cases = {
            "a { color: red; background: url(javascript:1); margin: 0 } b{font:12px 'x;y'}",
            "@import url(https://example.com/x.css); @import url(javascript:1); p{color:red}",
            "@media screen { p { color:red; background: url(javascript:1) } img { width: 1px } }",
            "@font-face { font-family: x; src: url(javascript:1); } p{color:red}",
            "p{background:url(//cdn/x.png);color:red}",
            "p{background:url(img/x.png);color:red}",
            "p{background:url(data:image/png;base64,AAAA);color:red}",
            "@import '&#106;avascript:1'; p{color:red}",
            "p { color: red /* never closed; div { color: blue }",
            "p { color:red;; ; margin:0 }",
            "p{background:url(oops;color:red} b{color:blue}",
            "p { font-family:'oops;color:red } b{color:blue}",
            "/* a comment */ p{color:red} /* c2 */",
            "p{color:red} p{color:red}",
            "*[x]:hover > .a#b + c { color: #fff; --v: calc(1px + var(--y, url(https://x/i.png))) }",
            "p{background:\\75 rl(javascript:1);color:red}",
            "p{content:'url(javascript:1)';color:red}",
            "@namespace url(javascript:1); p{color:red}",
            "body{background:url(https://example.com/a.png)}",
        };
        for (String c : cases) {
            System.out.println("IN : "+c.replace("\n","\\n"));
            System.out.println("OUT: "+clean(c));
            System.out.println();
        }
        // isolation
        Document d = Jsoup.parseBodyFragment("<style>p{color:red;background:url(javascript:1)}</style>", "https://example.com/a/b");
        String before = d.body().html();
        new Cleaner(sl()).clean(d);
        System.out.println("input unchanged: " + before.equals(d.body().html()));
        Document c1 = new Cleaner(sl()).clean(d);
        Document c2 = new Cleaner(sl()).clean(c1);
        System.out.println("idempotent: " + c1.body().html().equals(c2.body().html()));
        System.out.println(c1.body().html());
    }
}
