    /**
     Finds the '}' that closes a block, skipping strings, comments, escapes, parentheses, and nested braces. A '{'
     inside a function never starts a nested block, but a '}' is always honored as the block boundary even when a
     function was left unclosed: that is the same pragmatic parse-error recovery a browser performs, and it keeps
     the following rules independently parseable rather than letting the unclosed function swallow the rest.
     */
    private int matchingBrace(String value, int from, int end) {
        int depth = 1;
        int parenDepth = 0;
        int i = from;
        while (i < end) {
            char c = value.charAt(i);
            if (c == '\\') { i += 2; continue; }
            if (c == '"' || c == '\'') {
                int[] quote = sc.scanQuoted(value, i + 1, c);
                i = quote[1] == 1 ? quote[0] + 1 : quote[0]; // closed quote, or recovery at a newline/';'/EOF
                continue;
            }
            if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
                int close = value.indexOf("*/", i + 2);
                if (close < 0) return -1;
                i = close + 2;
                continue;
            }
            if (c == '(') {
                parenDepth++;
            } else if (c == ')') {
                if (parenDepth > 0) parenDepth--;
            } else if (c == '{' && parenDepth == 0) {
                depth++;
            } else if (c == '}') {
                depth--;
                if (depth == 0) return i;
            }
            i++;
        }
        return -1;
    }
}

