203	                    String cleaned = safelist.cleanStyleSheet(parent.normalName(), (Element) parent, data);
204	                    if (cleaned == null) { // this data node's rules were all invalid
205	                        numDiscarded++;
206	                        rejectedStyleElements.add(destination);
207	                    } else {
208	                        if (!cleaned.equals(data)) numDiscarded++; // rules or declarations were dropped/normalized
209	                        keptStyleElements.add(destination);
210	                        destination.appendChild(new DataNode(cleaned));
211	                    }
212	                } else {
213	                    destination.appendChild(new DataNode(data));
214	                }
215	            } else { // else, we don't care about comments, xml proc instructions, etc
