221	            if (source instanceof Element && safelist.isSafeTag(source.normalName())) {
222	                Element self = destination;
223	                destination = destination.parent(); // would have descended, so pop destination stack
224	                boolean rejected = rejectedStyleElements.remove(self);
225	                boolean kept = keptStyleElements.remove(self);
226	                if (rejected && !kept) self.remove(); // remove a <style> element whose content was wholly invalid
227	            }
228	        }
